<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gadgets Admin</title><link rel="stylesheet" href="admin.css"></head><body><aside><h2>GADGETS</h2><a href="#dashboard">Dashboard</a><a href="#products">Products</a><a href="#orders">Orders</a><a href="#chatbot">Chatbot & Quick Messages</a><a href="#agents">Agents</a><a href="#settings">Store & Social</a></aside><main><h1>Admin Panel</h1><p class="muted">Manage products, orders, chatbot messages and support agents.</p><section class="stats"><div>Products <b id="products">—</b></div><div>Orders <b id="orders">—</b></div><div>Agents <b id="agents">—</b></div></section><section class="panel"><h2>Product details</h2><form id="productForm"><input name="name" required placeholder="Product name"><input name="category" required placeholder="Category"><input name="price" required type="number" placeholder="Price"><input name="icon" placeholder="Icon / emoji"><textarea name="details" placeholder="Product details"></textarea><button>Save product</button></form></section><section class="panel"><h2>Chatbot quick messages</h2><textarea id="quick" rows="6" placeholder="One message per line"></textarea><button onclick="saveQuick()">Save messages</button></section><section class="panel"><h2>Contact agents</h2><form id="agentForm"><input name="name" required placeholder="Agent name"><input name="phone" placeholder="Phone"><input name="email" type="email" placeholder="Email"><button>Add agent</button></form></section><section class="panel"><h2>Store & social links</h2><p>Store settings are stored in <code>store_settings</code> and can be connected to your preferred admin editor.</p></section></main><script src="admin.js"></script></body></html>